description:
Write a generic record and generic static methods:

```java
// Pair.java
record Pair<A, B>(A first, B second) {
    static <A, B> Pair<A, B> of(A first, B second)
    Pair<B, A> swap()
}

// Generics.java
class Generics {
    static <T extends Comparable<? super T>> T max(Collection<T> items)  // NoSuchElementException when empty
    static double sum(Collection<? extends Number> numbers)
    static void fill(List<? super Integer> target, int from, int to)      // adds from, from+1, ..., to-1
    static <K, V> Map<V, List<K>> invert(Map<K, V> map)                    // keys grouped by value
    static <T> List<Pair<T, T>> pairs(List<T> items)                      // [a, b, c, d] gives [(a, b), (c, d)]; an odd last item is dropped
}
```

The bound on `max` must also accept `LocalDate`, which implements `Comparable<ChronoLocalDate>` rather than `Comparable<LocalDate>`.

`invert` returns a `LinkedHashMap` and keeps both the values and each list of keys in the order the map gives them, so with a `LinkedHashMap` or `TreeMap` input the result is predictable.

solution.Pair.java:
record Pair<A, B>(A first, B second) {
    static <A, B> Pair<A, B> of(A first, B second) { return new Pair<>(first, second); }

    Pair<B, A> swap() { return new Pair<>(second, first); }
}

solution.Generics.java:
import java.util.*;

class Generics {
    static <T extends Comparable<? super T>> T max(Collection<T> items) {
        if (items.isEmpty()) throw new NoSuchElementException("no items");
        T best = null;
        for (T item : items) {
            if (best == null || item.compareTo(best) > 0) best = item;
        }
        return best;
    }

    static double sum(Collection<? extends Number> numbers) {
        double total = 0;
        for (Number n : numbers) total += n.doubleValue();
        return total;
    }

    static void fill(List<? super Integer> target, int from, int to) {
        for (int i = from; i < to; i++) target.add(i);
    }

    static <K, V> Map<V, List<K>> invert(Map<K, V> map) {
        Map<V, List<K>> result = new LinkedHashMap<>();
        for (Map.Entry<K, V> e : map.entrySet()) {
            List<K> keys = result.get(e.getValue());
            if (keys == null) {
                keys = new ArrayList<>();
                result.put(e.getValue(), keys);
            }
            keys.add(e.getKey());
        }
        return result;
    }

    static <T> List<Pair<T, T>> pairs(List<T> items) {
        List<Pair<T, T>> result = new ArrayList<>();
        for (int i = 0; i + 1 < items.size(); i += 2) result.add(Pair.of(items.get(i), items.get(i + 1)));
        return result;
    }
}

unitTests:
test("pairs", () -> {
    Pair<String, Integer> p = Pair.of("apples", 4);
    checkEq(p.first(), "apples");
    checkEq(p.swap(), new Pair<>(4, "apples"));
    checkEq(Generics.pairs(List.of("a", "b", "c", "d", "e")), List.of(Pair.of("a", "b"), Pair.of("c", "d")));
    checkEq(Generics.pairs(List.of()).size(), 0);
});

test("max for any comparable type", () -> {
    checkEq(Generics.max(List.of(4, 9, 2)), 9);
    checkEq(Generics.max(Set.of("pear", "apple", "fig")), "pear");
    checkEq(Generics.max(List.of(java.time.LocalDate.of(2026, 1, 5), java.time.LocalDate.of(2025, 12, 31))), java.time.LocalDate.of(2026, 1, 5));
    checkThrows(NoSuchElementException.class, () -> Generics.max(new ArrayList<Integer>()));
});

test("wildcards", () -> {
    checkNear(Generics.sum(List.of(1, 2, 3)), 6);
    checkNear(Generics.sum(List.of(1.5, 2.25)), 3.75);
    checkNear(Generics.sum(Set.of(10L)), 10);
    List<Number> numbers = new ArrayList<>();
    List<Object> objects = new ArrayList<>(List.of("x"));
    Generics.fill(numbers, 0, 3);
    Generics.fill(objects, 5, 7);
    checkEq(numbers, List.of(0, 1, 2));
    checkEq(objects, List.of("x", 5, 6));
});

test("inverting a map", () -> {
    Map<String, String> owner = new LinkedHashMap<>();
    owner.put("pen", "ada");
    owner.put("mug", "bob");
    owner.put("cup", "ada");
    Map<String, List<String>> inv = Generics.invert(owner);
    checkEq(new ArrayList<>(inv.keySet()), List.of("ada", "bob"));
    checkEq(inv.get("ada"), List.of("pen", "cup"));
    Map<Integer, List<String>> byLength = Generics.invert(new TreeMap<>(Map.of("fig", 3, "kiwi", 4, "pea", 3)));
    checkEq(byLength.get(3), List.of("fig", "pea"));
});

